//! ♻️ The actual changed-path producer transfers admitted keys only after complete original key equality.
use super::*;
use crate::{list::persistent::{PersistentList,PersistentSet},named_edit::PersistentRankedKeys,retained_clone::{RetainedCloneRef,RetainedCloneSource,RetainedCloneSourceAdmission,RETAINED_CLONE_BULK_PAGE_BYTES}};
/// 🪡️ Private production and original issuance prevent an arbitrary root from borrowing an admitted directory.
pub struct KeyPreservingPersistentSet<T:RetireOwned+Send+Sync+'static>{index:Option<AdmittedNamedKeyIndex>,set:Option<PersistentSet<T>>,authored:Option<RetainedCloneBinding>,candidate:ManuallyDrop<Option<PersistentList<T>>>,source:ManuallyDrop<Option<RetainedCloneSource<PersistentList<T>>>>,admission:ManuallyDrop<Option<RetainedCloneSourceAdmission<PersistentList<T>,PersistentList<T>>>>,retirement:RetainedCloneClose,key:fn(&T)->&str,rank:usize,offset:usize,phase:u8,refused:bool,closing:bool}
impl<T:RetireOwned+Send+Sync+'static> KeyPreservingPersistentSet<T>{
 pub fn constructor_demand()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<Self>()*2+size_of::<AdmittedNamedKeyIndex>()*2,capacity_bytes:0,depth:1,..Default::default()}}
 pub fn new(rank:usize,key:fn(&T)->&str,index:&mut Option<AdmittedNamedKeyIndex>,grant:RetainedCloneGrant)->crate::RetainedWorkOutcome<Option<(Self,RetainedCloneProgress)>>{let mut work=0;let result=(||{let d=Self::constructor_demand();if !retained_clone_grant_admits(grant,d){return Ok(None);}let owned=index.as_ref().ok_or_else(invalid)?;if !owned.ready()||rank>=owned.len||owned.projection!=key as usize{return Err(invalid());}work=1;Ok(Some((Self{index:Some(index.take().ok_or_else(invalid)?),set:None,authored:None,candidate:ManuallyDrop::new(None),source:ManuallyDrop::new(None),admission:ManuallyDrop::new(None),retirement:Default::default(),key,rank,offset:0,phase:0,refused:false,closing:false},RetainedCloneProgress{retained_capacity_bytes:d.capacity_bytes,..paid(d)})))})();crate::RetainedWorkOutcome{result,work}}
 fn validate(&self,original:RetainedCloneRef<'_,PersistentList<T>>,authored:RetainedCloneRef<'_,SealedShared<T>>)->Result<(),ValueError>{if self.closing||self.refused||self.phase>7{return Err(invalid());}if self.phase<=4{self.index.as_ref().ok_or_else(invalid)?.check_source(&PersistentRankedKeys{original,key:self.key})?;}if self.authored.is_some()&&!authored.check_binding(&self.authored)?{return Err(invalid());}Ok(())}
 fn key_overhead(&self,original:RetainedCloneRef<'_,PersistentList<T>>)->Result<RetirementDemand,ValueError>{let mut d=PersistentRankedKeys{original,key:self.key}.rank_demand(self.rank)?;d.copy_bytes=d.copy_bytes.checked_add(size_of::<RetainedCloneRef<'_,str>>()*2+size_of::<SealedShared<T>>()+size_of::<usize>()*6).ok_or_else(invalid)?;Ok(d)}
 fn key_page(&self,overhead:usize,body:usize)->usize{(body.saturating_sub(overhead)/2).max(1).min(RETAINED_CLONE_BULK_PAGE_BYTES/2)}
 pub fn demand(&self,original:RetainedCloneRef<'_,PersistentList<T>>,authored:RetainedCloneRef<'_,SealedShared<T>>,body:usize)->Result<RetirementDemand,ValueError>{self.validate(original,authored)?;match self.phase{
  0=>Ok(fixed(authored.binding_copy_bytes())),
  1=>{let mut d=self.key_overhead(original)?;d.copy_bytes+=self.key_page(d.copy_bytes,body)*2;Ok(d)},
  2=>if let Some(set)=self.set.as_ref(){set.demand(original,authored)}else{Ok(RetirementDemand{copy_bytes:size_of::<PersistentSet<T>>()*2+size_of::<Option<PersistentSet<T>>>()*2,capacity_bytes:0,depth:1,..Default::default()})},
  3=>self.set.as_ref().ok_or_else(invalid)?.take_demand(),
  4=>match self.admission.as_ref(){Some(admission)if admission.phase()!="ready"=>admission.next_demand(),_=>Ok(RetirementDemand{copy_bytes:RetainedCloneSource::<PersistentList<T>>::constructor_copy_bytes()+size_of::<PersistentList<T>>()*2+size_of::<RetainedCloneSource<PersistentList<T>>>()*2+size_of::<RetainedCloneSourceAdmission<PersistentList<T>,PersistentList<T>>>()*2,depth:1,..Default::default()})},
  5=>RetainedCloneBinding::close_demand(&self.index.as_ref().ok_or_else(invalid)?.original,body),
  6=>Ok(fixed(self.source.as_ref().ok_or_else(invalid)?.borrow().binding_copy_bytes()+size_of::<AdmittedNamedKeyIndex>())),
  7=>Ok(Default::default()),_=>Err(invalid())
 }}
 pub fn advance(&mut self,original:RetainedCloneRef<'_,PersistentList<T>>,authored:RetainedCloneRef<'_,SealedShared<T>>,grant:RetainedCloneGrant)->crate::RetainedWorkOutcome{let mut work=0;let result=(||{
  let d=self.demand(original,authored,grant.maximum_copy_bytes)?;if self.phase==7{return Ok(RetainedCloneStep::Complete(Default::default()))}if !retained_clone_grant_admits(grant,d){return Ok(RetainedCloneStep::Progress(Default::default()))}
  let mut p=paid(d);match self.phase{
   0=>{take_work!(work,authored.bind(&mut self.authored,grant)).ok_or_else(invalid)?;self.phase=1;work+=1;},
   1=>{let source=PersistentRankedKeys{original,key:self.key};let(left,_)=take_work!(work,source.observe_key(self.rank,grant)).ok_or_else(invalid)?;let right=authored.project(self.key as usize,|row|(self.key)(row.get()));let left=left.get().as_bytes();let right=right.get().as_bytes();work+=1;let overhead=self.key_overhead(original)?.copy_bytes;let count=self.key_page(overhead,grant.maximum_copy_bytes).min(left.len().saturating_sub(self.offset));p.copied_bytes=overhead+count*2;if left.len()!=right.len(){self.refused=true;work+=1;}else{let end=self.offset.checked_add(count).ok_or_else(invalid)?;for i in self.offset..end{work+=1;if left[i]!=right[i]{self.refused=true;break;}}self.offset=end;work+=1;if !self.refused&&end==left.len(){self.phase=2;}}if self.refused{return Err(ValueError::literal(ValueRefusalKind::InvalidValue,"immutable named replacement changes its original key").with_retained_progress(p));}},
   2=>{if let Some(set)=self.set.as_mut(){let step=take_work!(work,set.advance(original,authored,grant));p=step.progress();if set.output_ready(){self.phase=3;work+=1;}}else{self.set=Some(PersistentSet::new(self.rank));work+=1;}},
   3=>{let(root,receipt)=take_work!(work,self.set.as_mut().ok_or_else(invalid)?.take(grant)).ok_or_else(invalid)?;*self.candidate=Some(root);self.phase=4;p=crate::retained_clone::admit_retained_clone_progress(grant,receipt,"named replacement root take")?;},
   4=>{if self.admission.is_none(){let root=self.candidate.take().ok_or_else(invalid)?;*self.admission=Some(RetainedCloneSource::<PersistentList<T>>::admission_owned(root,()));work+=1;}else{let admission=self.admission.as_mut().ok_or_else(invalid)?;if admission.phase()=="ready"{let turn=admission.take_output(&mut self.source,grant);work+=turn.work;p=turn.result?.progress();if admission.terminal_is_empty(){self.admission.take();self.phase=5;work+=1;}}else{let turn=admission.advance(grant);work+=turn.work;p=turn.result?.progress();}}},
   5=>{let index=self.index.as_mut().ok_or_else(invalid)?;if index.original.is_some(){p=take_work!(work,RetainedCloneBinding::close_one(&mut index.original,grant)).progress();}if index.original.is_none(){self.phase=6;work+=1;}},
   6=>{take_work!(work,self.source.as_ref().ok_or_else(invalid)?.borrow().bind(&mut self.index.as_mut().ok_or_else(invalid)?.original,grant)).ok_or_else(invalid)?;self.phase=7;work+=1;},
   _=>return Err(invalid()),
  }Ok(if self.output_ready(){RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})
 })();crate::RetainedWorkOutcome{result,work}}

 pub fn refused(&self)->bool{self.refused}
 pub fn output_ready(&self)->bool{!self.closing&&!self.refused&&self.phase==7&&self.source.is_some()&&self.index.as_ref().is_some_and(|index|index.ready())}
 pub fn take_demand(&self)->Result<RetirementDemand,ValueError>{if !self.output_ready(){return Err(invalid());}Ok(RetirementDemand{copy_bytes:size_of::<RetainedCloneSource<PersistentList<T>>>()*2+size_of::<AdmittedNamedKeyIndex>()*2+size_of::<u8>(),release_bytes:0,depth:1,..Default::default()})}
 pub fn take(&mut self,grant:RetainedCloneGrant)->crate::RetainedWorkOutcome<Option<((RetainedCloneSource<PersistentList<T>>,AdmittedNamedKeyIndex),RetainedCloneProgress)>>{let mut work=0;let result=(||{let d=self.take_demand()?;if !retained_clone_grant_admits(grant,d){return Ok(None);}self.phase=8;work+=1;Ok(Some(((self.source.take().ok_or_else(invalid)?,self.index.take().ok_or_else(invalid)?),RetainedCloneProgress{released_bytes:d.release_bytes,..paid(d)})))})();crate::RetainedWorkOutcome{result,work}}
 pub fn begin_close(&mut self){self.closing=true;if let Some(set)=self.set.as_mut(){set.begin_close();}if let Some(index)=self.index.as_mut(){index.begin_close();}}
 pub fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid());}if let Some(set)=self.set.as_ref(){return if set.terminal_is_empty(){Ok(fixed(size_of::<PersistentSet<T>>()*2))}else{set.close_demand(body)};}if let Some(index)=self.index.as_ref(){return if index.terminal_is_empty(){Ok(fixed(size_of::<AdmittedNamedKeyIndex>()*2))}else{index.close_demand(body)};}if let Some(admission)=self.admission.as_ref(){return admission.next_return_demand();}if !self.retirement.is_empty()||self.candidate.is_some(){return self.retirement.next_owner_demands::<PersistentList<T>>(self.candidate.is_some(),&None,body);}if let Some(source)=self.source.as_ref(){return if source.terminal_is_empty(){Ok(fixed(size_of::<RetainedCloneSource<PersistentList<T>>>()*2))}else{source.next_close_demand(body)};}RetainedCloneBinding::close_demand(&self.authored,body)}
 pub fn close_step(&mut self,grant:RetainedCloneGrant)->crate::RetainedWorkOutcome{let mut work=0;let result=(||{
  if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()))}
  let d=self.close_demand(grant.maximum_copy_bytes)?;if !retained_clone_grant_admits(grant,d){return Ok(RetainedCloneStep::Progress(Default::default()))}let p=paid(d);
  if let Some(set)=self.set.as_mut(){if set.terminal_is_empty(){self.set=None;work+=1;return Ok(RetainedCloneStep::Progress(p))}let step=take_work!(work,set.close_step(grant));return Ok(RetainedCloneStep::Progress(step.progress()))}
  if let Some(index)=self.index.as_mut(){if index.terminal_is_empty(){self.index=None;work+=1;return Ok(RetainedCloneStep::Progress(p))}let step=take_work!(work,index.close_step(grant));return Ok(RetainedCloneStep::Progress(step.progress()))}
  if let Some(admission)=self.admission.as_mut(){let mut returned=None;let turn=admission.return_inputs(&mut returned,grant);work+=turn.work;if let Some((root,()))=returned{*self.candidate=Some(root);}if admission.terminal_is_empty(){self.admission.take();}return turn.result.map(|step|RetainedCloneStep::Progress(step.progress()))}
  if !self.retirement.is_empty(){let step=take_work!(work,self.retirement.step_granted(grant));return Ok(RetainedCloneStep::Progress(step.progress()))}
  if let Some(step)=take_work!(work,self.retirement.begin_granted(&mut self.candidate,grant)){return Ok(RetainedCloneStep::Progress(step.progress()))}
  if let Some(source)=self.source.as_mut(){if source.terminal_is_empty(){*self.source=None;work+=1;return Ok(RetainedCloneStep::Progress(p))}let step=take_work!(work,source.close_step(grant));return Ok(RetainedCloneStep::Progress(step.progress()))}
  let step=take_work!(work,RetainedCloneBinding::close_one(&mut self.authored,grant));Ok(step)
 })();crate::RetainedWorkOutcome{result,work}}

 pub fn terminal_is_empty(&self)->bool{self.set.is_none()&&self.index.is_none()&&self.source.is_none()&&self.admission.is_none()&&self.candidate.is_none()&&self.retirement.is_empty()&&self.authored.is_none()}
}
impl<T:RetireOwned+Send+Sync+'static> Drop for KeyPreservingPersistentSet<T>{fn drop(&mut self){let empty=self.terminal_is_empty();assert!(std::thread::panicking()||empty,"key-preserving producer retains original typed custody until funded closure");if empty{unsafe{ManuallyDrop::drop(&mut self.candidate);ManuallyDrop::drop(&mut self.source);ManuallyDrop::drop(&mut self.admission);}}}}
